async def execute(title=None, content=None, category=None, summary=None):
    """Create a document.page from free text."""
    if not title or not str(title).strip():
        return json.dumps({
            'error': "Missing required argument 'title'",
            'parameter': 'title',
            'expected': 'a non-empty page title',
            'actual': '(empty)',
            'retryable': True,
        })
    vals = {
        'name': str(title).strip(),
        'type': 'content',
    }
    parent_id = _resolve_category(category)
    if parent_id:
        vals['parent_id'] = parent_id
    if summary and str(summary).strip():
        vals['draft_summary'] = str(summary).strip()
    page = env['document.page'].create(vals)
    if content is not None and str(content).strip():
        # The inverse writes the history row and re-points history_head.
        page.write({'content': str(content)})
        page.invalidate_recordset()
        if not page.history_head:
            return json.dumps({
                'error': 'Page %s was created but no history row exists — '
                         'the content did not reach document.page.history'
                         % page.id,
                'parameter': 'content',
                'expected': 'a document.page.history row after write',
                'actual': 'history_head is empty',
                'retryable': False,
            })
    return json.dumps({
        'id': page.id,
        'title': page.name,
        'history_id': page.history_head.id if page.history_head else None,
        'category': page.parent_id.name or None,
    }, ensure_ascii=False, default=str)


def _resolve_category(name):
    """Return the id of the category named `name`, creating it on miss."""
    if not name or not str(name).strip():
        return None
    name = str(name).strip()
    page = env['document.page'].search(
        [('name', '=ilike', name), ('type', '=', 'category')], limit=1)
    if not page:
        page = env['document.page'].create({
            'name': name, 'type': 'category'})
    return page.id

async def execute(model=None, res_id=None, title=None, content=None,
                  category=None, summary=None):
    """Create a document.page documenting an Odoo record."""
    if not model or not str(model).strip():
        return json.dumps({
            'error': "Missing required argument 'model'",
            'parameter': 'model',
            'expected': 'an Odoo model technical name',
            'actual': '(empty)',
            'retryable': True,
        })
    model = str(model).strip()
    if res_id is None or str(res_id).strip() == '':
        return json.dumps({
            'error': "Missing required argument 'res_id'",
            'parameter': 'res_id',
            'expected': 'an integer record id',
            'actual': '(empty)',
            'retryable': True,
        })
    try:
        res_id = int(res_id)
    except (TypeError, ValueError):
        return json.dumps({
            'error': "Invalid value for 'res_id'",
            'parameter': 'res_id',
            'expected': 'an integer record id',
            'actual': str(res_id),
            'retryable': True,
        })
    if model not in env.registry:
        return json.dumps({
            'error': 'Unknown model: %s' % model,
            'parameter': 'model',
            'expected': 'an installed Odoo model',
            'actual': model,
            'retryable': False,
        })
    # Reuse the AI core's scoped-model check (odoo-model-tools 2.2) — do
    # not invent a second one. Same function odoo_search/odoo_create use.
    _tools = __import__(
        'odoo.addons.ai_agent_core.core.tools',
        fromlist=['_model_scope_error'])
    scope_err = _tools._model_scope_error(env, model)
    if scope_err:
        return json.dumps({
            'error': scope_err,
            'parameter': 'model',
            'expected': 'a model within the session scope',
            'actual': model,
            'retryable': False,
        })
    record = env[model].browse(res_id).exists()
    if not record:
        return json.dumps({
            'error': '%s #%s not found' % (model, res_id),
            'parameter': 'res_id',
            'expected': 'an existing %s id' % model,
            'actual': str(res_id),
            'retryable': False,
        })
    if not title or not str(title).strip():
        title = '%s %s' % (model, record.display_name)
    if content is None or not str(content).strip():
        content = _default_record_summary(record)
    vals = {
        'name': str(title).strip(),
        'type': 'content',
    }
    parent_id = _resolve_category(category)
    if parent_id:
        vals['parent_id'] = parent_id
    if summary and str(summary).strip():
        vals['draft_summary'] = str(summary).strip()
    page = env['document.page'].create(vals)
    page.write({'content': str(content)})
    page.invalidate_recordset()
    if not page.history_head:
        return json.dumps({
            'error': 'Page %s was created but no history row exists — '
                     'the content did not reach document.page.history'
                     % page.id,
            'parameter': 'content',
            'expected': 'a document.page.history row after write',
            'actual': 'history_head is empty',
            'retryable': False,
        })
    return json.dumps({
        'id': page.id,
        'title': page.name,
        'history_id': page.history_head.id,
        'source': '%s,%s' % (model, res_id),
        'category': page.parent_id.name or None,
    }, ensure_ascii=False, default=str)


def _default_record_summary(record):
    """A short deterministic summary when the agent supplies no content."""
    lines = ['<h1>%s</h1>' % record.display_name]
    for fname in ('name', 'description', 'state'):
        if fname not in record._fields:
            continue
        value = record[fname]
        if not value:
            continue
        lines.append('<p><strong>%s:</strong> %s</p>'
                     % (fname, str(value)[:2000]))
    return '\n'.join(lines)


